  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Attempts to place the head pipe from the queue at the user-supplied row and column
   *          letter. On success, the pipe is consumed from the queue, the map cell is updated, the
   *          placement is recorded on the cell stack, and the step counter is incremented.
   * Algorithm:
   *   1. Convert the column char to an internal column index: colIndex = col - 'A' + 1.
   *   2. Peek the head pipe from pipeQueue.
   *   3. If map.tryPlacePipe(row, colIndex, headPipe) returns true:
   *        a. Consume the head pipe from pipeQueue.
   *        b. Push the just-placed FillableCell onto cellStack.
   *        c. Increment numOfSteps.
   *        d. Return true.
   *   4. Otherwise return false.
   * Related Features: numOfSteps : int, cellStack : CellStack, map : Map, pipeQueue : PipeQueue
   * Related Classes: PipeQueue, Map, FillableCell, CellStack, Pipe
   * Input:
   *   - row : int - the player-facing row index, in [1..rows-2] (aligned with internal playable rows).
   *   - col : char - the column letter, in ['A'..cols-2 mapped letter], e.g. 'A' represents internal col 1.
   * Output: boolean - true if the pipe was placed successfully, false if placement was rejected.
   * Pre-condition: The Game is initialized, the head pipe exists, and the row/col represent a valid playable cell that is currently empty and fillable.
   * Post-condition: On true, the chosen playable cell holds the head pipe, the pipe is removed from the queue, a corresponding FillableCell is pushed on the cell stack, and numOfSteps is incremented by 1.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean placePipe(final int row, final char col)
  {
    int colIndex = col - 'A' + 1;
    Pipe headPipe = getPipeQueue().peek();
    if (getMap().tryPlacePipe(row, colIndex, headPipe))
    {
      getPipeQueue().consume();
      FillableCell placedCell = (FillableCell) getMap().getCell()[row][colIndex];
      getCellStack().push(placedCell);
      setNumOfSteps(getNumOfSteps() + 1);
      return true;
    }
    return false;
  }

